<script setup>import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import InputError from '@/Components/InputError.vue'; import {Head,Link,useForm} from '@inertiajs/vue3'; const props=defineProps({token:String,headers:Array,rows:Array}); const upload=useForm({file:null}); const mapping=useForm({token:props.token,mapping:{name:'',asset_type:'',site:'',vendor:'',model:'',firmware_version:'',internal_ip:'',external_ip:'',criticality:'',data_source_type:''}}); const fields=[['name','Device name *'],['asset_type','Asset type *'],['site','Site name *'],['vendor','Vendor'],['model','Model'],['firmware_version','Firmware'],['internal_ip','Internal IP'],['external_ip','External IP'],['criticality','Criticality'],['data_source_type','Monitoring source']];</script>
<template><Head title="Import assets"/><AuthenticatedLayout><template #header><h1 class="text-xl font-semibold">Import assets from CSV</h1></template><div class="mx-auto max-w-4xl px-4 py-8"><div v-if="!token" class="rounded-xl border bg-white p-8 shadow-sm"><h2 class="text-lg font-semibold">Choose your inventory file</h2><p class="mt-2 text-sm text-slate-600">Your spreadsheet can use any column names. You will match them to asset fields in the next step.</p><form @submit.prevent="upload.post(route('assets.import.preview'))" class="mt-6"><input type="file" accept=".csv,text/csv" required @change="upload.file=$event.target.files[0]" class="block w-full rounded-lg border border-dashed border-slate-300 p-6"/><InputError class="mt-2" :message="upload.errors.file"/><div class="mt-5 flex justify-end gap-3"><Link :href="route('assets.index')" class="px-4 py-2 text-sm">Cancel</Link><button class="rounded-lg bg-teal-700 px-5 py-2 text-sm font-semibold text-white">Review columns</button></div></form></div><form v-else @submit.prevent="mapping.post(route('assets.import.store'))" class="rounded-xl border bg-white p-6 shadow-sm"><h2 class="text-lg font-semibold">Match your columns</h2><p class="mt-1 text-sm text-slate-600">Required fields must be mapped. Sites must already exist and names must match.</p><div class="mt-6 grid gap-4 sm:grid-cols-2"><div v-for="([field,label]) in fields" :key="field"><label class="mb-1 block text-sm font-medium">{{ label }}</label><select v-model="mapping.mapping[field]" :required="['name','asset_type','site'].includes(field)" class="w-full rounded-lg border-slate-300"><option value="">Do not import</option><option v-for="header in headers" :key="header" :value="header">{{ header }}</option></select></div></div><InputError class="mt-3" :message="mapping.errors.mapping"/><div class="mt-6 overflow-auto rounded-lg border"><table class="min-w-full text-xs"><thead class="bg-slate-50"><tr><th v-for="header in headers" :key="header" class="px-3 py-2 text-left">{{ header }}</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="index" class="border-t"><td v-for="(value,i) in row" :key="i" class="whitespace-nowrap px-3 py-2">{{ value }}</td></tr></tbody></table></div><div class="mt-6 flex justify-end"><button class="rounded-lg bg-teal-700 px-5 py-2 text-sm font-semibold text-white">Import assets</button></div></form></div></AuthenticatedLayout></template>
